-- Job 313: the registry of grocery chains and their apps (supabase/retailers/retailers.json), a
-- store's link to one chain and its chosen app, and the three calls the app makes: which chains
-- a typed store name matches, the answer to "Is this <chain>?", and the questions for stores
-- created before the registry. The data block at the end is generated by scripts/retailers.ts.

create table public.retailers (
  chain text not null check (chain ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  country text not null check (country ~ '^[A-Z]{2}$'),
  name text not null check (name <> ''),
  aliases text[] not null default '{}',
  web text,
  -- [{name, android, ios, universalLink}], the first one the chain's default (loyalty) app.
  apps jsonb not null check (jsonb_typeof(apps) = 'array'),
  primary key (chain, country)
);
alter table public.retailers enable row level security;
-- Signed-out callers read no table (supabase/tests/least_privilege.test.sql); guests are
-- authenticated, so everyone who has a store can read the registry.
create policy retailers_read on public.retailers for select to authenticated using (true);
revoke all on public.retailers from public, anon, authenticated;
grant select on public.retailers to authenticated;

alter table public.stores
  add column retailer_chain text,
  add column retailer_country text,
  -- The android package of one of the chain's apps; null is the chain's first app.
  add column retailer_app text,
  -- The household said yes or no to a chain for this store: never asked again.
  add column retailer_answered boolean not null default false;
alter table public.stores add constraint stores_retailer_fkey
  foreign key (retailer_chain, retailer_country) references public.retailers (chain, country)
  on delete set null;
create index stores_retailer on public.stores (retailer_chain, retailer_country);

-- A name as matching compares it: lower case, diacritics and ß folded, every run of other
-- characters one space ("É.Leclerc" -> "e leclerc", "Aldi Süd" -> "aldi sud").
create function public.retailer_key(p_name text) returns text
language sql immutable set search_path = '' as $$
  select btrim(regexp_replace(
    translate(
      replace(replace(replace(lower(coalesce(p_name, '')), 'ß', 'ss'), 'æ', 'ae'), 'œ', 'oe'),
      'àáâãäåāăąçćčďđèéêëēėęěìíîïīįłñńňòóôõöøōőŕřśšşșťțùúûüūůűųýÿźżž',
      'aaaaaaaaacccddeeeeeeeeiiiiiilnnnoooooooorrssssttuuuuuuuuyyzzz'),
    '[^a-z0-9]+', ' ', 'g'));
$$;

-- The chains a store name names. Exact: the name is a chain's name or alias, or starts with one
-- and a space ("lidl am markt"); of several, only the longest alias counts ("aldi süd am bahnhof"
-- is ALDI SÜD, not every Aldi); when p_country has exact matches, other countries' are dropped
-- ("Aldi" on a German phone is ALDI Nord and ALDI SÜD, "Hofer" there still Hofer AT). Then the
-- chains whose name or alias starts with the typed text (two characters or more).
create function public.match_retailers(p_name text, p_country text)
returns table (chain text, country text, name text, apps jsonb, exact boolean)
language sql stable set search_path = '' as $$
  with typed as (select public.retailer_key(p_name) as k),
  keys as (
    select r.chain, r.country, r.name, r.apps, public.retailer_key(a) as key
    from public.retailers r cross join lateral unnest(array_prepend(r.name, r.aliases)) a
  ),
  exact as (
    select keys.chain, keys.country, keys.name, keys.apps, max(char_length(keys.key)) as len
    from keys, typed
    where typed.k <> '' and (typed.k = keys.key or typed.k like keys.key || ' %')
    group by keys.chain, keys.country, keys.name, keys.apps
  ),
  longest as (select * from exact where len = (select max(len) from exact)),
  kept as (
    select * from longest l
    where l.country = upper(p_country)
       or not exists (select from longest h where h.country = upper(p_country))
  ),
  prefix as (
    select distinct keys.chain, keys.country, keys.name, keys.apps
    from keys, typed
    where char_length(typed.k) >= 2 and keys.key like typed.k || '%'
      and not exists (select from exact e where e.chain = keys.chain and e.country = keys.country)
  ),
  found as (
    select kept.chain, kept.country, kept.name, kept.apps, true as exact from kept
    union all
    select prefix.chain, prefix.country, prefix.name, prefix.apps, false from prefix
  )
  select f.chain, f.country, f.name, f.apps, f.exact from found f
  order by f.exact desc, coalesce(f.country = upper(p_country), false) desc, f.name, f.country, f.chain
  limit 5;
$$;

-- The household's answer for one store: a chain (and optionally which of its apps) or, with
-- p_chain null, "none of these". Either way the store is not asked about again.
create function public.answer_store_retailer(
  p_store uuid, p_chain text, p_country text, p_app text default null
) returns void
language plpgsql set search_path = '' as $$
declare
  v_household uuid := (select household_id from public.stores where id = p_store);
  v_apps jsonb;
begin
  if v_household is null or not public.is_household_member(v_household) then
    raise exception 'not_a_member' using errcode = '42501';
  end if;
  if p_chain is null then
    if p_app is not null then
      raise exception 'retailer_app_without_chain' using errcode = '22023';
    end if;
    update public.stores
    set retailer_chain = null, retailer_country = null, retailer_app = null, retailer_answered = true
    where id = p_store;
    return;
  end if;
  v_apps := (select r.apps from public.retailers r where r.chain = p_chain and r.country = upper(p_country));
  if v_apps is null then
    raise exception 'unknown_retailer' using errcode = '22023';
  end if;
  if p_app is not null and not exists (
    select from jsonb_array_elements(v_apps) a where a ->> 'android' = p_app
  ) then
    raise exception 'unknown_retailer_app' using errcode = '22023';
  end if;
  update public.stores
  set retailer_chain = p_chain, retailer_country = upper(p_country), retailer_app = p_app,
      retailer_answered = true
  where id = p_store;
end $$;

-- "Is your Lidl the chain Lidl (Germany)?" for the household's stores that are not linked and
-- not answered: their exact matches that have an app, one row per store and chain.
create function public.retailer_questions(p_household uuid, p_country text)
returns table (store_id uuid, chain text, country text, name text, apps jsonb)
language sql stable set search_path = '' as $$
  select s.id, m.chain, m.country, m.name, m.apps
  from public.stores s
  cross join lateral public.match_retailers(s.name, p_country) m
  where s.household_id = p_household and public.is_household_member(p_household)
    and s.retailer_chain is null and not s.retailer_answered
    and m.exact and jsonb_array_length(m.apps) > 0
  order by s.sort_order, s.id, m.name, m.country;
$$;

revoke execute on function public.retailer_key(text) from public, anon;
revoke execute on function public.match_retailers(text, text) from public, anon;
revoke execute on function public.answer_store_retailer(uuid, text, text, text) from public, anon;
revoke execute on function public.retailer_questions(uuid, text) from public, anon;
grant execute on function public.retailer_key(text) to authenticated;
grant execute on function public.match_retailers(text, text) to authenticated;
grant execute on function public.answer_store_retailer(uuid, text, text, text) to authenticated;
grant execute on function public.retailer_questions(uuid, text) to authenticated;

